import pandas as pd
import numpy as np

def clean(df: pd.DataFrame) -> pd.DataFrame:
    df = df.copy()
    # drop exact duplicate rows
    df = df.drop_duplicates()
    # normalise Region whitespace and variants
    if "Region" in df.columns:
        df["Region"] = df["Region"].astype(object).apply(
            lambda x: x.strip() if isinstance(x, str) else x
        )
        df["Region"] = df["Region"].replace({"": np.nan, "nan": np.nan, "None": np.nan})
    # fix Category label variant
    if "Category" in df.columns:
        df["Category"] = df["Category"].replace({"Furnture": "Furniture"})
    # ensure numeric types
    for col in ["Order_ID", "Quantity", "Price", "Revenue"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")
    # enforce Revenue = Quantity * Price
    if {"Quantity", "Price"}.issubset(df.columns):
        df["Revenue"] = df["Quantity"] * df["Price"]
    # parse dates
    if "Date" in df.columns:
        df["Date"] = pd.to_datetime(df["Date"], errors="coerce")
    return df

def answer(df: pd.DataFrame) -> dict:
    df = clean(df)
    # month key YYYY-MM
    df = df.copy()
    if not pd.api.types.is_datetime64_any_dtype(df["Date"]):
        df["Date"] = pd.to_datetime(df["Date"], errors="coerce")
    df = df.dropna(subset=["Date"])
    df["month"] = df["Date"].dt.strftime("%Y-%m")
    grouped = df.groupby("month", dropna=True)["Revenue"].sum()
    out = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # return int when possible
        if pd.isna(v):
            out[k] = None
        else:
            fv = float(v)
            out[k] = int(fv) if fv.is_integer() else fv
    return out
